import sys


def main():
    data = sys.stdin.read().split('\n')
    idx = 0

    def nextline():
        nonlocal idx
        while idx < len(data):
            line = data[idx]
            idx += 1
            return line.strip()
        return None

    first = nextline()
    while first is not None and first == '':
        first = nextline()
    if first is None:
        sys.stdout.write("ERR\n")
        return
    try:
        k = int(first)
    except ValueError:
        sys.stdout.write("ERR\n")
        return

    prog = []
    for _ in range(k):
        raw = nextline()
        line = "" if raw is None else raw.strip()
        parts = line.split()
        op = parts[0].upper() if parts else "BAD"
        arg = None
        if op == "PUSH":
            if len(parts) == 2:
                try:
                    arg = int(parts[1])
                except ValueError:
                    op = "BAD"
            else:
                op = "BAD"
        elif op == "JNZ":
            if len(parts) == 2:
                try:
                    arg = int(parts[1])
                except ValueError:
                    op = "BAD"
            else:
                op = "BAD"
        elif op in ("POP", "ADD", "SUB", "MUL", "DUP", "SWAP", "PRINT", "HALT"):
            if len(parts) != 1:
                op = "BAD"
        else:
            op = "BAD"
        prog.append((op, arg))

    stack = []
    out = []
    pc = 0
    steps = 0

    def fail():
        sys.stdout.write("ERR\n")

    def pop():
        if not stack:
            raise IndexError("empty stack")
        return stack.pop()

    try:
        while True:
            if steps >= 10000:
                fail()
                return
            steps += 1
            if pc < 0 or pc >= len(prog):
                fail()
                return
            op, arg = prog[pc]
            if op == "PUSH":
                stack.append(arg)
            elif op == "POP":
                pop()
            elif op == "ADD":
                a = pop()
                b = pop()
                stack.append(b + a)
            elif op == "SUB":
                a = pop()
                b = pop()
                stack.append(b - a)
            elif op == "MUL":
                a = pop()
                b = pop()
                stack.append(b * a)
            elif op == "DUP":
                if not stack:
                    fail()
                    return
                stack.append(stack[-1])
            elif op == "SWAP":
                if len(stack) < 2:
                    fail()
                    return
                stack[-1], stack[-2] = stack[-2], stack[-1]
            elif op == "PRINT":
                out.append(str(pop()))
            elif op == "JNZ":
                v = pop()
                if v != 0:
                    if arg < 0 or arg >= len(prog):
                        fail()
                        return
                    pc = arg
                    continue
            elif op == "HALT":
                if out:
                    sys.stdout.write('\n'.join(out) + '\n')
                return
            else:
                fail()
                return
            pc += 1
    except IndexError:
        fail()


main()
